_SOURCES = json.loads('{"__init__":"\\"\\"\\"Truco Cu\\u00e1ntico: original hackathon implementation, October 2026.\\"\\"\\"\\n","gates":"\\"\\"\\"Fixed rotation catalogue shared by the deck and Qiskit circuit builder.\\"\\"\\"\\nimport math\\nANGLES = {\'pi/2\': math.pi/2, \'pi/6\': math.pi/6, \'-pi/6\': -math.pi/6,\\n          \'pi/3\': math.pi/3, \'pi/67\': math.pi/67}\\nROTATIONS = {f\'{axis}:{name}\': (axis.lower(), angle)\\n             for axis in (\'RX\', \'RY\', \'RZ\') for name, angle in ANGLES.items()}\\n# Compatibility aliases for saved circuits; the new deck uses explicit angles.\\nROTATIONS.update({\'RY+\': (\'ry\', math.pi/6), \'RY-\': (\'ry\', -math.pi/6)})\\nVALID = (\'H\', \'X\', \'Z\', *ROTATIONS)\\nDECK = (\'H\',)*6 + (\'X\',) + (\'Z\',)*3 + tuple(g for g in ROTATIONS if \':\' in g)*2\\n","classic":"\\"\\"\\"Pure rules for the specified two-player, no-Flor variant.\\"\\"\\"\\nfrom dataclasses import dataclass\\nfrom itertools import combinations\\nfrom .gates import DECK as GATES\\n\\nNUMBERS = (1, 2, 3, 4, 5, 6, 7, 10, 11, 12)\\nSUITS = (\'espada\', \'basto\', \'oro\', \'copa\')\\nLINK = {\'espada\': \'copa\', \'copa\': \'espada\', \'basto\': \'oro\', \'oro\': \'basto\'}\\n\\n@dataclass(frozen=True)\\nclass Card:\\n    number: int\\n    suit: str\\n    def __post_init__(self):\\n        if self.number not in NUMBERS or self.suit not in SUITS:\\n            raise ValueError(\'Carta inv\\u00e1lida\')\\n    def linked(self):\\n        return Card(self.number, LINK[self.suit])\\n    def data(self):\\n        return {\'number\': self.number, \'suit\': self.suit, \'label\': f\'{self.number} de {self.suit}\'}\\n\\nDECK = tuple(Card(n, s) for n in NUMBERS for s in SUITS)\\nPAIRS = tuple((Card(n, s), Card(n, s).linked()) for n in NUMBERS for s in (\'espada\', \'basto\'))\\nSPECIAL = {(1, \'espada\'): 14, (1, \'basto\'): 13, (7, \'espada\'): 12, (7, \'oro\'): 11}\\nRANK = {3: 10, 2: 9, 1: 8, 12: 7, 11: 6, 10: 5, 7: 4, 6: 3, 5: 2, 4: 1}\\n\\ndef strength(card):\\n    return SPECIAL.get((card.number, card.suit), RANK[card.number])\\n\\ndef deal(rng):\\n    cards = [rng.choice(pair) for pair in rng.sample(PAIRS, 6)]\\n    rng.shuffle(cards)\\n    return [cards[:3], cards[3:]]\\n\\ndef envido(cards):\\n    value = lambda c: c.number if c.number <= 7 else 0\\n    same = [20 + value(a) + value(b) for a, b in combinations(cards, 2) if a.suit == b.suit]\\n    return max(same) if same else max(map(value, cards))\\n\\ndef hand_winner(bazas, mano):\\n    \\"\\"\\"None means undecided. -1 marks a parda; players are 0 and 1.\\"\\"\\"\\n    if not bazas:\\n        return None\\n    if len(bazas) >= 2:\\n        first, second = bazas[:2]\\n        if first == -1 and second != -1:\\n            return second\\n        if first != -1 and (second == first or second == -1):\\n            return first\\n    if len(bazas) == 3:\\n        first, second, third = bazas\\n        if third != -1:\\n            return third\\n        return next((p for p in (first, second) if p != -1), mano)\\n    return None\\n\\nENVIDO_CHAINS = {\\n    (): (\'envido\', \'real\', \'falta\'),\\n    (\'envido\',): (\'envido\', \'real\', \'falta\'),\\n    (\'envido\', \'envido\'): (\'real\', \'falta\'),\\n    (\'real\',): (\'falta\',),\\n    (\'envido\', \'real\'): (\'falta\',),\\n    (\'envido\', \'envido\', \'real\'): (\'falta\',),\\n}\\n\\ndef envido_value(chain, scores=None, loser=None):\\n    if chain[-1] == \'falta\':\\n        if scores is None:\\n            raise ValueError(\'Falta necesita el marcador\')\\n        return 15 - max(scores)\\n    return sum({\'envido\': 2, \'real\': 3}[c] for c in chain)\\n\\ndef refusal_value(chain):\\n    return envido_value(chain[:-1]) if len(chain) > 1 else 1\\n\\n\\n\\nclass GateDeck:\\n    def __init__(self, rng):\\n        self.rng = rng\\n        self.draw_pile = list(GATES)\\n        self.discard = []\\n        rng.shuffle(self.draw_pile)\\n    def draw_hand(self):\\n        if len(self.draw_pile) < 8:\\n            self.draw_pile.extend(self.discard)\\n            self.discard.clear()\\n            self.rng.shuffle(self.draw_pile)\\n        return [[self.draw_pile.pop() for _ in range(4)] for _ in range(2)]\\n    def discard_hand(self, hands):\\n        self.discard.extend(g for hand in hands for g in hand)\\n","quantum":"\\"\\"\\"Qiskit previews and explicit measurement sources. No game scoring here.\\"\\"\\"\\nimport math\\nimport random\\nfrom dataclasses import dataclass, field\\nfrom qiskit import QuantumCircuit\\nfrom qiskit.quantum_info import Statevector, DensityMatrix, Operator, Kraus\\nimport numpy as np\\n\\nfrom .gates import VALID, ROTATIONS\\n\\n# Educational seconds, deliberately not an IonQ device calibration.\\nNOISE_T1 = 60.0\\nNOISE_TPHI = 90.0\\nNOISE_T2 = 1 / (1 / (2 * NOISE_T1) + 1 / NOISE_TPHI)\\n\\ndef noisy_state(gates, seconds):\\n    if type(seconds) not in (int, float) or not math.isfinite(seconds) or seconds < 0:\\n        raise ValueError(\'Tiempo de ruido inv\\u00e1lido\')\\n    state = DensityMatrix.from_instruction(circuit(gates))\\n    gamma = -math.expm1(-seconds / NOISE_T1)\\n    amplitude = Kraus([np.diag([1, math.sqrt(1-gamma)]),\\n                       np.array([[0, math.sqrt(gamma)], [0, 0]])])\\n    # A random Z with probability p attenuates coherence by 1-2p.\\n    p = -math.expm1(-seconds / NOISE_TPHI) / 2\\n    dephasing = Kraus([math.sqrt(1-p)*np.eye(2), math.sqrt(p)*np.diag([1,-1])])\\n    return state.evolve(amplitude).evolve(dephasing)\\n\\ndef noise_view(gates, seconds, ideal=None):\\n    data = dict(ideal or preview(gates))\\n    state = noisy_state(gates, seconds)\\n    matrix = state.data\\n    vector = [float(2*matrix[0,1].real), float(-2*matrix[0,1].imag),\\n              float((matrix[0,0]-matrix[1,1]).real)]\\n    x,y,z = data[\'steps\'][-1][\'bloch\']\\n    path = []\\n    for i in range(25):\\n        t = seconds*i/24\\n        path.append([x*math.exp(-t/NOISE_T2), y*math.exp(-t/NOISE_T2),\\n                     1+(z-1)*math.exp(-t/NOISE_T1)])\\n    data.update(probabilities=[float(p) for p in state.probabilities()], bloch=vector,\\n                density_matrix=[[[float(v.real),float(v.imag)] for v in row] for row in matrix],\\n                purity=float(state.purity().real), amplitudes=None, relative_phase=None,\\n                noise_trajectory=path,\\n                noise={\'seconds\':seconds,\'t1\':NOISE_T1,\'tphi\':NOISE_TPHI,\'t2\':NOISE_T2,\\n                       \'model\':\'amplitude damping + dephasing; educational time scale\',\\n                       \'ideal_probabilities\':data[\'steps\'][-1][\'probabilities\']})\\n    return data\\n\\ndef circuit(gates, measured=False):\\n    if not isinstance(gates, (list, tuple)) or len(gates) > 3 or any(g not in VALID for g in gates):\\n        raise ValueError(\'Circuito inv\\u00e1lido: hasta tres compuertas\')\\n    qc = QuantumCircuit(1, 1) if measured else QuantumCircuit(1)\\n    for gate in gates:\\n        if gate == \'H\': qc.h(0)\\n        elif gate == \'X\': qc.x(0)\\n        elif gate == \'Z\': qc.z(0)\\n        else:\\n            axis, angle = ROTATIONS[gate]\\n            getattr(qc, axis)(angle, 0)\\n    if measured: qc.measure(0, 0)\\n    return qc\\n\\ndef preview(gates):\\n    steps = []\\n    for i in range(len(gates) + 1):\\n        state = Statevector.from_instruction(circuit(gates[:i]))\\n        a, b = state.data\\n        cross = a.conjugate() * b\\n        phase = None if abs(a) < 1e-12 or abs(b) < 1e-12 else float(math.atan2(cross.imag, cross.real))\\n        steps.append({\'gate\': gates[i-1] if i else \'|0\\u27e9\',\\n                      \'amplitudes\': [[float(z.real), float(z.imag)] for z in (a, b)],\\n                      \'probabilities\': [float(p) for p in state.probabilities()],\\n                      \'bloch\': [float(2 * cross.real), float(2 * cross.imag), float(abs(a)**2 - abs(b)**2)],\\n                      \'relative_phase\': phase})\\n    # Partial rotations for a physically consistent Bloch trajectory.\\n    # H is a pi rotation around (X+Z)/sqrt(2), equivalent up to global phase.\\n    trajectory = [steps[0][\'bloch\']]\\n    segments = []\\n    for i, gate in enumerate(gates):\\n        start = len(trajectory) - 1\\n        state = Statevector.from_instruction(circuit(gates[:i]))\\n        axis, angle = ROTATIONS.get(gate, (None, math.pi))\\n        for t in range(1, 25):\\n            theta = angle * t / 24\\n            partial = QuantumCircuit(1)\\n            if axis: getattr(partial, axis)(theta, 0)\\n            elif gate == \'X\': partial.rx(theta, 0)\\n            elif gate == \'Z\': partial.rz(theta, 0)\\n            else:\\n                h = np.array([[1,1],[1,-1]]) / math.sqrt(2)\\n                partial.unitary(Operator(math.cos(theta/2)*np.eye(2)-1j*math.sin(theta/2)*h), [0])\\n            a, b = state.evolve(partial).data\\n            cross = a.conjugate()*b\\n            trajectory.append([float(2*cross.real),float(2*cross.imag),float(abs(a)**2-abs(b)**2)])\\n        segments.append({\'gate\':gate, \'start\':start, \'end\':len(trajectory)-1})\\n    return {\'gates\': list(gates), \'steps\': steps, \'trajectory\':trajectory, \'segments\':segments, **steps[-1]}\\n\\n@dataclass\\nclass QuantumCard:\\n    index: int\\n    tokens: list\\n    sequence: list = field(default_factory=list)\\n    locked: bool = False\\n    result: int | None = None\\n    record: dict | None = None\\n    noise_enabled: bool = False\\n    noise_seconds: float = 0.0\\n    _preview: dict | None = field(default=None, repr=False)\\n    def edit(self, indices):\\n        if self.locked: raise ValueError(\'Circuito confirmado: no puede cambiar\')\\n        if not isinstance(indices, (list, tuple)) or len(indices) > 3 or any(type(i) is not int or not 0 <= i < len(self.tokens) for i in indices) or len(set(indices)) != len(indices):\\n            raise ValueError(\'Cada ficha se usa una vez; m\\u00e1ximo tres\')\\n        self.sequence = list(indices)\\n        self._preview = None\\n        return self.view()\\n    @property\\n    def gates(self):\\n        return [self.tokens[i] for i in self.sequence]\\n    def view(self):\\n        if self._preview is None: self._preview = preview(self.gates)\\n        return noise_view(self.gates, self.noise_seconds, self._preview) if self.noise_enabled else self._preview\\n    def age(self, seconds):\\n        if type(seconds) not in (int,float) or not math.isfinite(seconds) or not 0 <= seconds <= 5:\\n            raise ValueError(\'Intervalo de ruido inv\\u00e1lido\')\\n        if self.noise_enabled and self.locked and self.result is None:\\n            self.noise_seconds += seconds\\n    def collapse(self, bit, record):\\n        if not self.locked: raise ValueError(\'Confirm\\u00e1 antes de medir\')\\n        if self.result is not None: raise ValueError(\'La carta ya fue medida\')\\n        if type(bit) is not int or bit not in (0, 1): raise ValueError(\'Resultado inv\\u00e1lido\')\\n        self.result, self.record = bit, record\\n\\nclass LocalSampler:\\n    name = \'LOCAL DEVELOPMENT \\u2014 Qiskit Statevector; NO IonQ\'\\n    def sample(self, gates, noise_seconds=None):\\n        state = Statevector.from_instruction(circuit(gates)) if noise_seconds is None else noisy_state(gates, noise_seconds)\\n        bit = int(state.sample_memory(1)[0])\\n        return bit, {\'backend\': self.name if noise_seconds is None else \'LOCAL DEVELOPMENT \\u2014 Qiskit DensityMatrix; NO IonQ\', \'shots\': 1, \'gates\': list(gates), \'result\': bit,\\n                     \'method\': \'Qiskit Statevector.sample_memory(1)\' if noise_seconds is None else \'Qiskit DensityMatrix.sample_memory(1)\',\\n                     **({\'noise\':{\'seconds\':noise_seconds,\'t1\':NOISE_T1,\'tphi\':NOISE_TPHI,\'t2\':NOISE_T2,\\n                                  \'probabilities\':[float(p) for p in state.probabilities()]}} if noise_seconds is not None else {})}\\n\\ndef effective_sample(distribution, rng=None):\\n    \\"\\"\\"One effective draw from validated one-qubit probabilities/counts.\\"\\"\\"\\n    weights = [0.0, 0.0]\\n    for key, value in distribution.items():\\n        key = str(key).replace(\' \', \'\')\\n        if key in (\'0\', \'0x0\'): bit = 0\\n        elif key in (\'1\', \'0x1\'): bit = 1\\n        else: raise ValueError(\'Orden/formato de bits no reconocido: se esperaba un bit\')\\n        value = float(value)\\n        if not math.isfinite(value) or value < 0: raise ValueError(\'Distribuci\\u00f3n inv\\u00e1lida\')\\n        weights[bit] += value\\n    total = sum(weights)\\n    if not total or not math.isfinite(total): raise ValueError(\'Resultado sin probabilidades v\\u00e1lidas\')\\n    return int((rng or random.SystemRandom()).random() >= weights[0] / total)\\n","remote":"\\"\\"\\"Adapter for Qollab\'s documented injected Qiskit backend.\\n\\nNo credentials, provider construction or undocumented network endpoints.\\nLifecycle is polled by the UI so it stays responsive. Never substitutes local data.\\n\\"\\"\\"\\nimport time\\nfrom qiskit.providers.jobstatus import JobStatus\\nfrom .quantum import circuit, effective_sample\\n\\nclass RemoteMeasurement:\\n    def __init__(self, backend, one_job=True):\\n        self.backend = backend\\n        self.one_job = one_job\\n        self.sent = False\\n        self.job = None\\n        self.gates = []\\n        self.cached = None\\n        self.started = None\\n        self.last_error = None\\n        self.submission_uncertain = False\\n    def info(self):\\n        name = getattr(self.backend,\'name\',\'unknown\')\\n        if callable(name): name = name()\\n        config = self.backend.configuration() if hasattr(self.backend,\'configuration\') else None\\n        simulator = getattr(config,\'simulator\',None) if config else None\\n        module = type(self.backend).__module__\\n        return {\'name\':str(name),\'module\':module,\'simulator\':simulator,\\n                \'noise_model\':str(getattr(getattr(self.backend,\'options\',None),\'noise_model\',None))}\\n    def start(self, sequences):\\n        if self.job is not None: return  # resumes the SAME job after timeout\\n        if self.submission_uncertain:\\n            raise RuntimeError(\'El env\\u00edo anterior tiene estado incierto. No se enviar\\u00e1 otro job que pueda duplicar la medici\\u00f3n\')\\n        info = self.info()\\n        if \'ionq\' not in (info[\'name\']+\' \'+info[\'module\']).lower():\\n            raise ValueError(\'Seleccion\\u00e1 un simulador IonQ; este backend no est\\u00e1 identificado como IonQ\')\\n        if info[\'simulator\'] is not True and \'simulator\' not in info[\'name\'].lower():\\n            raise ValueError(\'No se verific\\u00f3 que el backend sea simulador. No se enviar\\u00e1 a hardware\')\\n        if self.sent and self.one_job:\\n            raise ValueError(\'Qollab permite un solo job IonQ por ejecuci\\u00f3n. No se inventar\\u00e1 una segunda medici\\u00f3n\')\\n        if not sequences: raise ValueError(\'No hay circuitos para medir\')\\n        circuits = [circuit(g, measured=True) for g in sequences]\\n        self.gates = [list(g) for g in sequences]\\n        self.sent = True  # fail closed after uncertain submission; avoid duplicate jobs\\n        self.started = time.monotonic()\\n        try:\\n            self.job = self.backend.run(circuits if len(circuits)>1 else circuits[0], shots=1)\\n        except Exception as exc:\\n            self.submission_uncertain = True\\n            message = str(exc).lower()\\n            recognized = next((p for p in (\'only one\',\'one job\',\'xhr\',\'xmlhttprequest\',\'keyword\',\'connection\',\'not supported\',\'unexpected\') if p in message), \'unclassified\')\\n            self.last_error = {\'type\':type(exc).__name__,\'recognized\':recognized}\\n            raise RuntimeError(f\'Fall\\u00f3 el env\\u00edo ({type(exc).__name__}; {recognized}); estado remoto incierto. No se reenviar\\u00e1 autom\\u00e1ticamente\') from None\\n    def poll(self):\\n        if self.cached is not None: return {\'done\':True,\'measurements\':self.cached}\\n        if self.job is None: raise ValueError(\'No hay job remoto para consultar\')\\n        status = self.job.status()\\n        if status in (JobStatus.ERROR,JobStatus.CANCELLED):\\n            self.last_error = str(status)\\n            raise RuntimeError(\'IonQ inform\\u00f3 error o cancelaci\\u00f3n; no hay resultado de juego\')\\n        if status != JobStatus.DONE:\\n            if time.monotonic()-self.started>120:\\n                raise TimeoutError(\'IonQ sigue pendiente. Reintentar consulta retoma el mismo job\')\\n            return {\'done\':False,\'status\':str(status)}\\n        try:\\n            result = self.job.result()\\n            measurements = []\\n            for i, gates in enumerate(self.gates):\\n                # A single bit: only 0/1 or 0x0/0x1 allowed. No low-probability filtering.\\n                counts = result.get_counts(i)\\n                bit = effective_sample(counts)\\n                job_id = str(self.job.job_id()) if hasattr(self.job,\'job_id\') else None\\n                record = {\'backend\':self.info(),\'shots\':1,\'gates\':gates,\'result\':bit,\\n                          \'job_id\':job_id,\'distribution\':dict(counts),\\n                          \'method\':\'one effective sample from returned counts/probabilities\'}\\n                measurements.append((bit,record))\\n            self.cached = measurements\\n            return {\'done\':True,\'measurements\':measurements}\\n        except Exception as exc:\\n            self.last_error = type(exc).__name__\\n            raise RuntimeError(\'No se pudo validar el resultado IonQ; no se asign\\u00f3 una identidad\') from None\\n    def release(self):\\n        self.job = None; self.cached = None; self.started = None\\n","game":"\\"\\"\\"Interface-independent state machine. Private projections are explicit.\\"\\"\\"\\nimport random\\nfrom datetime import datetime, timezone\\nfrom .classic import Card, deal, strength, envido, hand_winner, ENVIDO_CHAINS, envido_value, refusal_value, GateDeck\\nfrom .quantum import QuantumCard\\n\\nLABELS = {\'envido\':\'Envido\', \'real\':\'Real Envido\', \'falta\':\'Falta Envido\',\\n          \'truco\':\'Truco\', \'retruco\':\'Retruco\', \'vale4\':\'Vale Cuatro\',\\n          \'accept\':\'Quiero\', \'reject\':\'No quiero\', \'fold\':\'Irse al mazo\',\\n          \'reassert\':\'Reafirmar canto\', \'confirm\':\'Confirmar circuito\',\\n          \'next\':\'Nueva mano\'}\\n\\nclass Game:\\n    def __init__(self, names, rng=None, privacy=False, noise=False):\\n        if not isinstance(names, (list, tuple)) or len(names) != 2 or any(not isinstance(n,str) or not n.strip() or len(n)>30 for n in names):\\n            raise ValueError(\'Ingres\\u00e1 dos nombres de hasta 30 caracteres\')\\n        self.names = [n.strip() for n in names]\\n        if type(privacy) is not bool: raise ValueError(\\"Privacidad inv\\u00e1lida\\")\\n        self.privacy = privacy\\n        if type(noise) is not bool: raise ValueError(\'Ruido inv\\u00e1lido\')\\n        self.noise = noise\\n        self.rng = rng or random.SystemRandom()\\n        self.scores = [0,0]\\n        self.mano = self.rng.randrange(2)\\n        self.gate_deck = GateDeck(self.rng)\\n        self.history = []\\n        self.hand_number = 0\\n        self.new_hand()\\n    def new_hand(self):\\n        self.hand_number += 1\\n        self.cards = deal(self.rng)\\n        self.tokens = self.gate_deck.draw_hand()\\n        self.q = [None, None]\\n        self.played = [set(), set()]\\n        self.table = []\\n        self.bazas = []\\n        self.events = []\\n        self.actor = self.mano\\n        self.turn = self.mano\\n        self.phase = \'prepare\'\\n        self.stake = 1\\n        self.truco_right = None\\n        self.pending = None\\n        self.suspended = None\\n        self.envido_done = False\\n        self.envido_result = None\\n        self.measure_context = None\\n        self.measure_requests = []\\n        self.last_public_measurement = None\\n        self.winner = None\\n        self.event(\'Reparto de mano\', mano=self.mano)\\n    def event(self, text, **data):\\n        self.events.append({\'text\':text, \'time\':datetime.now(timezone.utc).isoformat(), **data})\\n    def effective_card(self, player, index):\\n        card = self.cards[player][index]\\n        q = self.q[player]\\n        return card.linked() if q is not None and q.index == index and q.result == 1 else card\\n    def can_envido(self):\\n        return not self.envido_done and not self.bazas and self.stake == 1 and not self.played[self.actor]\\n    def legal(self):\\n        if self.phase == \'prepare\': return [\'choose\',\'edit\',\'confirm\']\\n        if self.phase == \'play\':\\n            result = [\'play\',\'fold\']\\n            if self.can_envido(): result += list(ENVIDO_CHAINS[()])\\n            if self.stake < 4 and (self.stake == 1 or self.truco_right == self.actor):\\n                result += [{1:\'truco\',2:\'retruco\',3:\'vale4\'}[self.stake]]\\n            return result\\n        if self.phase == \'respond\':\\n            result = [\'accept\',\'reject\']\\n            if self.pending[\'kind\'] == \'envido\':\\n                result += list(ENVIDO_CHAINS.get(tuple(self.pending[\'chain\']), ()))\\n            else:\\n                if self.pending[\'level\'] < 4:\\n                    result += [{2:\'retruco\',3:\'vale4\'}[self.pending[\'level\']]]\\n                if self.can_envido(): result += list(ENVIDO_CHAINS[()])\\n            return result\\n        if self.phase == \'reassert\': return [\'reassert\']\\n        if self.phase == \'hand_end\': return [\'next\']\\n        return []\\n    def dispatch(self, action, value=None):\\n        if action not in self.legal(): raise ValueError(\'Acci\\u00f3n inv\\u00e1lida para este estado\')\\n        p = self.actor\\n        if action == \'choose\':\\n            if type(value) is not int or not 0 <= value < 3: raise ValueError(\'Carta inv\\u00e1lida\')\\n            self.q[p] = QuantumCard(value, self.tokens[p], noise_enabled=self.noise)\\n        elif action == \'edit\':\\n            if self.q[p] is None: raise ValueError(\'Eleg\\u00ed una carta\')\\n            self.q[p].edit(value)\\n        elif action == \'confirm\':\\n            if self.q[p] is None: raise ValueError(\'Eleg\\u00ed exactamente una carta\')\\n            self.q[p].locked = True\\n            other = 1-p\\n            if self.q[other] is None or not self.q[other].locked:\\n                self.actor = other\\n            else:\\n                self.phase = \'play\'; self.actor = self.turn = self.mano\\n        elif action in (\'envido\',\'real\',\'falta\'):\\n            if self.phase == \'respond\' and self.pending[\'kind\'] == \'envido\':\\n                chain = self.pending[\'chain\'] + [action]\\n            else:\\n                if self.phase == \'respond\': self.suspended = self.pending.copy()\\n                chain = [action]\\n            self.pending = {\'kind\':\'envido\',\'chain\':chain,\'proposer\':p}\\n            self.phase = \'respond\'; self.actor = 1-p\\n            self.event(\' \\u2192 \'.join(LABELS[c] for c in chain), player=p, kind=\'speech\', speech=action)\\n        elif action in (\'truco\',\'retruco\',\'vale4\'):\\n            level = {\'truco\':2, \'retruco\':3,\'vale4\':4}[action]\\n            # Raising a pending canto accepts its prior level implicitly.\\n            if self.phase == \'respond\': self.stake = self.pending[\'level\']\\n            self.pending = {\'kind\':\'truco\',\'level\':level,\'proposer\':p}\\n            self.phase = \'respond\'; self.actor = 1-p\\n            self.event(LABELS[action], player=p, kind=\'speech\', speech=action)\\n        elif action == \'reject\':\\n            self.event(\'No quiero\', player=p, kind=\'speech\', speech=\'reject\')\\n            pending = self.pending\\n            if pending[\'kind\'] == \'envido\':\\n                self.envido_done = True\\n                self.award(pending[\'proposer\'], refusal_value(pending[\'chain\']), \'Envido no querido\')\\n                self.pending = None\\n                if self.phase != \'match_end\': self.resume_truco()\\n            else:\\n                self.finish_hand(pending[\'proposer\'], pending[\'level\']-1, \'Truco no querido\')\\n        elif action == \'accept\':\\n            self.event(\'Quiero\', player=p, kind=\'speech\', speech=\'accept\')\\n            if self.pending[\'kind\'] == \'truco\':\\n                self.stake = self.pending[\'level\']; self.truco_right = p\\n                self.pending = None; self.phase = \'play\'; self.actor = self.turn\\n            else:\\n                self.envido_done = True\\n                self.envido_acceptor = p\\n                self.begin_measure(\'envido\', [self.mano,1-self.mano])\\n        elif action == \'reassert\':\\n            self.pending = self.suspended; self.suspended = None\\n            self.event(\'Truco reafirmado\', player=p, kind=\'speech\', speech=\'truco\')\\n            self.phase = \'respond\'; self.actor = 1-p\\n        elif action == \'play\':\\n            if type(value) is not int or not 0 <= value < 3 or value in self.played[p]:\\n                raise ValueError(\'Carta no disponible\')\\n            if self.q[p].index == value and self.q[p].result is None:\\n                self.play_intent = (p, value)\\n                self.begin_measure(\'play\', [p])\\n            else: self.commit_play(p, value)\\n        elif action == \'fold\':\\n            self.event(\'Al mazo\', player=p, kind=\'speech\', speech=\'fold\')\\n            self.finish_hand(1-p, self.stake, \'Al mazo\')\\n        elif action == \'next\':\\n            self.mano = 1-self.mano\\n            self.new_hand()\\n    def begin_measure(self, context, players):\\n        self.measure_context = context\\n        self.measure_requests = [p for p in players if self.q[p].result is None]\\n        self.phase = \'measure\'\\n        if not self.measure_requests: self.after_measure()\\n    def complete_measure(self, measurements):\\n        if self.phase != \'measure\' or not isinstance(measurements, (list, tuple)) or len(measurements) != len(self.measure_requests):\\n            raise ValueError(\'No hay medici\\u00f3n pendiente o lote incompleto\')\\n        if any(not isinstance(item, (list, tuple)) or len(item) != 2 or\\n               type(item[0]) is not int or item[0] not in (0,1) or not isinstance(item[1], dict)\\n               for item in measurements):\\n            raise ValueError(\'Medici\\u00f3n inv\\u00e1lida\')\\n        # Validate the whole batch before collapsing any card.\\n        if any(not self.q[p].locked or self.q[p].result is not None for p in self.measure_requests):\\n            raise ValueError(\'La carta no est\\u00e1 disponible para medir\')\\n        for p, (bit, record) in zip(self.measure_requests, measurements):\\n            self.q[p].collapse(bit, {**record,\'moment\':self.measure_context})\\n        self.measure_requests = []\\n        self.after_measure()\\n    def after_measure(self):\\n        if self.measure_context == \'envido\':\\n            self.resolve_envido()\\n        else:\\n            p, index = self.play_intent\\n            self.last_public_measurement = {\'player\':p, **self.quantum_report(p)}\\n            public = {k:v for k,v in self.last_public_measurement.items() if k in (\'player\',\'original\',\'linked\',\'preview\',\'result\')}\\n            self.event(\'Carta medida\', kind=\'measurement\', measurement=public)\\n            self.commit_play(p, index)\\n    def resolve_envido(self):\\n        values = [envido([self.effective_card(p,i) for i in range(3)]) for p in (0,1)]\\n        winner = self.mano if values[0] == values[1] else int(values[1] > values[0])\\n        points = envido_value(self.pending[\'chain\'], self.scores, 1-winner)\\n        self.envido_result = {\'values\':values,\'winner\':winner,\'points\':points}\\n        first = self.envido_acceptor\\n        self.event(\'Tantos de Envido\', kind=\'speech\', speech=\'envido_first\', player=first, value=values[first])\\n        other = 1-first\\n        self.event(\'Respuesta de tantos\', kind=\'speech\', speech=\'envido_answer\', player=other, value=values[other], better=values[other]>values[first], tie=values[other]==values[first], mano=other==self.mano)\\n        self.award(winner, points, \'Envido querido\', values=values)\\n        self.pending = None\\n        if self.phase != \'match_end\': self.resume_truco()\\n    def resume_truco(self):\\n        if self.suspended:\\n            self.phase = \'reassert\'; self.actor = self.suspended[\'proposer\']\\n        else:\\n            self.phase = \'play\'; self.actor = self.turn\\n    def commit_play(self, p, index):\\n        card = self.effective_card(p,index)\\n        self.played[p].add(index)\\n        self.table.append({\'player\':p,\'card\':card.data()})\\n        self.event(\'Carta jugada\', player=p, card=card.data())\\n        if len(self.table) % 2:\\n            self.turn = self.actor = 1-p; self.phase = \'play\'; return\\n        pair = self.table[-2:]\\n        ranks = [strength(Card(item[\'card\'][\'number\'], item[\'card\'][\'suit\'])) for item in pair]\\n        winner = -1 if ranks[0] == ranks[1] else pair[int(ranks[1] > ranks[0])][\'player\']\\n        self.bazas.append(winner)\\n        self.event(\'Baza parda\' if winner == -1 else \'Baza ganada\', winner=winner,\\n                   cards=list(pair), strengths=ranks)\\n        outcome = hand_winner(self.bazas,self.mano)\\n        if outcome is not None: self.finish_hand(outcome,self.stake,\'Mano ganada\')\\n        else:\\n            self.turn = self.actor = pair[0][\'player\'] if winner == -1 else winner\\n            self.phase = \'play\'\\n    def award(self, player, points, reason, **data):\\n        before = self.scores[player]\\n        self.scores[player] = min(15,self.scores[player]+points)\\n        self.event(reason, winner=player, points=points, gained=self.scores[player]-before, **data)\\n        if self.scores[player] == 15:\\n            self.winner = player; self.phase = \'match_end\'\\n            self.archive()\\n    def finish_hand(self, winner, points, reason):\\n        self.award(winner,points,reason)\\n        if self.phase != \'match_end\':\\n            self.winner = winner; self.archive()\\n            self.phase = \'hand_end\'\\n    def archive(self):\\n        if self.history and self.history[-1][\'hand\'] == self.hand_number: return\\n        self.history.append({\'hand\':self.hand_number,\'mano\':self.mano,\'scores\':list(self.scores),\\n                             \'quantum\':[self.quantum_report(p) for p in (0,1)],\\n                             \'cards\':[[{\'original\':self.cards[p][i].data(), \'effective\':self.effective_card(p,i).data(),\\n                                        \'played\':i in self.played[p], \'quantum\':self.q[p] is not None and self.q[p].index==i}\\n                                       for i in range(3)] for p in (0,1)],\\n                             \'events\':list(self.events),\'bazas\':list(self.bazas)})\\n        self.gate_deck.discard_hand(self.tokens)\\n    def quantum_report(self,p):\\n        q = self.q[p]\\n        if q is None: return None\\n        original = self.cards[p][q.index]\\n        return {\'original\':original.data(), \'linked\':original.linked().data(),\\n                \'tokens\':list(q.tokens),\'sequence\':list(q.sequence), \'preview\':q.view(),\\n                \'result\':q.result,\'record\':q.record,\'locked\':q.locked,\\n                \'discarded\':[g for i,g in enumerate(q.tokens) if i not in q.sequence],\\n                \'explanation\': \'Termin\\u00f3 sin producir un resultado cl\\u00e1sico.\' if q.result is None else\\n                f\'La medici\\u00f3n produjo {q.result}. La identidad permanece fija durante la mano.\'}\\n    def public_view(self):\\n        data = {\'names\':self.names,\'scores\':self.scores,\'mano\':self.mano,\'actor\':self.actor,\\n                \'phase\':self.phase,\'hand\':self.hand_number,\'stake\':self.stake,\\n                \'bazas\':self.bazas,\'table\':self.table,\'pending\':self.pending,\\n                \'envido\':self.envido_result,\'events\':self.events,\\n                \'actions\':[{\'id\':a,\'label\':LABELS.get(a,a),\'hint\':self.action_hint(a)} for a in self.legal() if a not in (\'choose\',\'edit\',\'play\')],\\n                \'winner\':self.winner, \'privacy\':self.privacy, \'noise\':self.noise}\\n        if self.last_public_measurement and self.phase != \'measure\':\\n            # The explicit public-play exception discloses circuit and preview, never tokens.\\n            data[\'public_measurement\'] = {k:v for k,v in self.last_public_measurement.items() if k in (\'player\',\'original\',\'linked\',\'preview\',\'result\',\'record\')}\\n        if self.phase == \'measure\' and self.measure_context == \'play\':\\n            p = self.play_intent[0]\\n            report = self.quantum_report(p)\\n            data[\'public_measurement\'] = {k:v for k,v in report.items() if k in (\'original\',\'linked\',\'preview\',\'result\')}\\n        if self.phase == \'match_end\': data[\'history\'] = self.history\\n        if self.phase in (\'hand_end\',\'match_end\'): data[\'report\'] = self.history[-1]\\n        return data\\n    def action_hint(self, action):\\n        if action == \'accept\':\\n            if self.pending[\'kind\'] == \'truco\':\\n                return f\\"La mano pasa a valer {self.pending[\'level\']} puntos. Despu\\u00e9s se sigue jugando.\\"\\n            chain = self.pending[\'chain\']\\n            stake = str(15-max(self.scores)) if chain[-1] == \'falta\' else str(envido_value(chain))\\n            return f\'El ganador suma {stake} puntos. Se miden las cartas cu\\u00e1nticas que a\\u00fan no se midieron.\'\\n        if action == \'reject\':\\n            pending = self.pending\\n            points = refusal_value(pending[\'chain\']) if pending[\'kind\'] == \'envido\' else pending[\'level\']-1\\n            ending = \'La mano contin\\u00faa.\' if pending[\'kind\'] == \'envido\' else \'La mano termina.\'\\n            if self.scores[pending[\'proposer\']] + points >= 15: ending = \'Llega a 15 y gana la partida.\'\\n            return f\\"{self.names[pending[\'proposer\']]} suma {points} {\'punto\' if points == 1 else \'puntos\'}. {ending}\\"\\n        if action == \'fold\':\\n            return f\\"{self.names[1-self.actor]} suma {self.stake} {\'punto\' if self.stake == 1 else \'puntos\'}. La mano termina.\\"\\n        if action in (\'truco\',\'retruco\',\'vale4\'):\\n            points = {\'truco\':2,\'retruco\':3,\'vale4\':4}[action]\\n            return f\'Si el rival acepta, la mano vale {points} puntos; si rechaza, gan\\u00e1s {points-1}.\'\\n        if action in (\'envido\',\'real\',\'falta\'):\\n            chain = self.pending[\'chain\'] + [action] if self.pending and self.pending[\'kind\'] == \'envido\' else [action]\\n            if action == \'falta\': return f\'Si acepta: {15-max(self.scores)} puntos, lo que le falta a quien va adelante para llegar a 15. Se define con los tantos.\'\\n            return f\'Si acepta: {envido_value(chain)} puntos por los tantos, aparte de la mano.\'\\n        return {\'reassert\':\'El rival debe responder al Truco que qued\\u00f3 pendiente.\',\\n                \'next\':\'Se reparten tres cartas nuevas y cambia el jugador mano.\'}.get(action, \'\')\\n    def private_view(self):\\n        if self.phase not in (\'prepare\',\'play\',\'respond\',\'reassert\'): return {}\\n        p = self.actor\\n        data = {\'player\':p,\'quantum\':self.quantum_report(p)}\\n        if self.phase in (\'prepare\',\'play\',\'respond\',\'reassert\'):\\n            data[\'cards\'] = [{**self.effective_card(p,i).data(),\'index\':i,\'played\':i in self.played[p],\\n                              \'quantum\':self.q[p] is not None and self.q[p].index == i} for i in range(3)]\\n        if self.phase == \'prepare\': data[\'tokens\'] = self.tokens[p]\\n        return data\\n","tutorial":"\\"\\"\\"Beginner lessons; ideal circuits and explicit educational noise experiments.\\"\\"\\"\\nLESSONS = [{\'title\': \'Bienvenido a la mesa\',\\n  \'title_en\': \'Welcome to the table\',\\n  \'text\': \'Bot Q te acompa\\u00f1a a aprender. Una mano es un reparto de tres cartas; una baza es una \'\\n          \'carta de cada jugador. La partida termina cuando alguien llega a 15 puntos. Vas a \'\\n          \'convertir una carta en la representaci\\u00f3n de un qubit: un sistema que medimos con dos \'\\n          \'resultados posibles.\',\\n  \'text_en\': \'Bot Q helps you learn. A hand is a deal of three cards; a trick (baza) is one card \'\\n             \'from each player. The first player to 15 points wins. You will turn a card into a \'\\n             \'representation of a qubit: a system measured with two possible results.\',\\n  \'example\': \'Original |0\\u27e9: 4 de oro. Ligada |1\\u27e9: 4 de basto. Conserva el 4 y cambia el palo. \'\\n             \'Espada se liga con copa; basto, con oro.\',\\n  \'example_en\': \'Original |0\\u27e9: 4 of coins (oro). Linked |1\\u27e9: 4 of clubs (basto). The rank stays 4; \'\\n                \'the suit changes. Swords pair with cups; clubs with coins.\',\\n  \'technical\': \'|0\\u27e9 y |1\\u27e9 son los estados de la base de medici\\u00f3n. El dibujo de dos cartas muestra \'\\n               \'resultados posibles de un \\u00fanico qubit; no son dos qubits ni hay entrelazamiento.\',\\n  \'technical_en\': \'|0\\u27e9 and |1\\u27e9 form the measurement basis. The two card images show possible \'\\n                  \'outcomes of one qubit; they are not two qubits and are not entangled.\',\\n  \'circuits\': [[]],\\n  \'sample\': False},\\n {\'title\': \'1 \\u00b7 X: cambiar de original a ligada\',\\n  \'title_en\': \'1 \\u00b7 X: from original to linked\',\\n  \'text\': \'Una compuerta es una operaci\\u00f3n sobre el estado del qubit. X intercambia los papeles de \'\\n          \'original y ligada. Empezando en original, X prepara la ligada con 100 % de probabilidad \'\\n          \'en el modelo ideal. Med\\u00ed para observar un resultado real.\',\\n  \'text_en\': \'A gate is an operation on a qubit state. X exchanges the roles of original and \'\\n             \'linked. Starting at original, X prepares linked with 100% probability in the ideal \'\\n             \'model. Measure to observe a real outcome.\',\\n  \'example\': \'Desde |0\\u27e9, una X \\u2192 ligada. Dos X \\u2192 original. X no quiere decir \\u201celegir siempre la \'\\n             \'ligada\\u201d: importa el estado que recibe.\',\\n  \'example_en\': \'From |0\\u27e9, one X \\u2192 linked; two X gates \\u2192 original. X does not mean \\u201calways choose \'\\n                \'linked\\u201d: its input state matters.\',\\n  \'technical\': \'X(\\u03b1|0\\u27e9 + \\u03b2|1\\u27e9) = \\u03b2|0\\u27e9 + \\u03b1|1\\u27e9. Equivale a una rotaci\\u00f3n de \\u03c0 (180\\u00b0) alrededor del \'\\n               \'eje X de la esfera, salvo fase global. La amplitud es el n\\u00famero que acompa\\u00f1a a \'\\n               \'cada estado; su magnitud al cuadrado es la probabilidad.\',\\n  \'technical_en\': \'X(\\u03b1|0\\u27e9 + \\u03b2|1\\u27e9) = \\u03b2|0\\u27e9 + \\u03b1|1\\u27e9. Up to global phase, this is a \\u03c0 (180\\u00b0) rotation \'\\n                  \'about the Bloch X axis. An amplitude is the coefficient of a basis state; its \'\\n                  \'squared magnitude is the probability.\',\\n  \'circuits\': [[\'X\']],\\n  \'sample\': True},\\n {\'title\': \'2 \\u00b7 H: dos posibilidades antes de medir\',\\n  \'title_en\': \'2 \\u00b7 H: two possibilities before measurement\',\\n  \'text\': \'H desde original prepara una superposici\\u00f3n: 50 % para original y 50 % para ligada. Esos \'\\n          \'porcentajes describen resultados posibles al medir, no una carta cl\\u00e1sica escondida. \'\\n          \'Aceptar Envido mide las cartas Q pendientes para calcular los tantos; el resultado \'\\n          \'queda fijo.\',\\n  \'text_en\': \'H from original prepares a superposition: 50% original and 50% linked. These \'\\n             \'percentages describe possible measurement outcomes, not a hidden classical card. \'\\n             \'Accepting Envido measures unresolved Q cards to calculate both totals; the result \'\\n             \'stays fixed.\',\\n  \'example\': \'Un solo experimento da 0 o 1, nunca \\u201cmedia carta\\u201d. Si repet\\u00eds muchos experimentos \'\\n             \'preparados igual, sus frecuencias se acercan a 50/50; diez repeticiones no tienen \'\\n             \'por qu\\u00e9 dar cinco de cada uno.\',\\n  \'example_en\': \'One experiment gives 0 or 1, never \\u201chalf a card\\u201d. Over many identically prepared \'\\n                \'experiments, frequencies approach 50/50; ten trials need not give exactly five of \'\\n                \'each.\',\\n  \'technical\': \'H|0\\u27e9 = (|0\\u27e9 + |1\\u27e9)/\\u221a2. P(0)=|1/\\u221a2|\\u00b2=1/2; P(1)=1/2. La regla de Born relaciona \'\\n               \'amplitudes y probabilidades. Se hace un \\u00fanico muestreo efectivo por carta y mano.\',\\n  \'technical_en\': \'H|0\\u27e9 = (|0\\u27e9 + |1\\u27e9)/\\u221a2. P(0)=|1/\\u221a2|\\u00b2=1/2; P(1)=1/2. The Born rule relates \'\\n                  \'amplitudes to probabilities. Each card is sampled effectively once per hand.\',\\n  \'circuits\': [[\'H\']],\\n  \'sample\': True},\\n {\'title\': \'3 \\u00b7 Rotaciones: importan el eje y el \\u00e1ngulo\',\\n  \'title_en\': \'3 \\u00b7 Rotations: axis and angle matter\',\\n  \'text\': \'RX, RY y RZ giran el estado alrededor de los ejes X, Y y Z de la esfera. Cada ficha \'\\n          \'tiene un \\u00e1ngulo fijo. La esfera es un mapa: norte es original, sur es ligada. La altura \'\\n          \'Z determina sus porcentajes; X e Y tambi\\u00e9n describen informaci\\u00f3n de fase y coherencia.\',\\n  \'text_en\': \'RX, RY and RZ rotate the state about the Bloch X, Y and Z axes. Each token has a \'\\n             \'fixed angle. The sphere is a map: north is original, south linked. Height Z sets the \'\\n             \'measurement percentages; X and Y also encode phase and coherence.\',\\n  \'example\': \'RY(\\u03c0/6) desde original da 93,3 % / 6,7 %. Despu\\u00e9s de H, la misma RY da 25 % / 75 %. \'\\n             \'Una ficha no tiene un porcentaje fijo: opera sobre lo que dej\\u00f3 la anterior.\',\\n  \'example_en\': \'RY(\\u03c0/6) from original gives 93.3% / 6.7%. After H, the same RY gives 25% / 75%. A \'\\n                \'gate does not have a fixed percentage: it acts on the previous state.\',\\n  \'technical\': \'\\u03c0 radianes = 180\\u00b0; \\u03c0/2 = 90\\u00b0; \\u03c0/6 = 30\\u00b0; \\u2212\\u03c0/6 = \\u221230\\u00b0. RY(\\u03b8)|0\\u27e9 = cos(\\u03b8/2)|0\\u27e9 + \'\\n               \'sin(\\u03b8/2)|1\\u27e9. RZ cambia fase sin cambiar inmediatamente los porcentajes al medir en \'\\n               \'Z. Girar la c\\u00e1mara no aplica ninguna compuerta.\',\\n  \'technical_en\': \'\\u03c0 radians = 180\\u00b0; \\u03c0/2 = 90\\u00b0; \\u03c0/6 = 30\\u00b0; \\u2212\\u03c0/6 = \\u221230\\u00b0. RY(\\u03b8)|0\\u27e9 = cos(\\u03b8/2)|0\\u27e9 + \'\\n                  \'sin(\\u03b8/2)|1\\u27e9. RZ changes phase without immediately changing Z-measurement \'\\n                  \'percentages. Rotating the camera applies no gate.\',\\n  \'circuits\': [[\'H\', \'RY:pi/6\'],\\n               [\'H\', \'RY:-pi/6\'],\\n               [\'RY:pi/6\'],\\n               [\'RX:pi/2\'],\\n               [\'H\', \'RZ:pi/2\', \'H\']],\\n  \'sample\': True},\\n {\'title\': \'4 \\u00b7 Fase e interferencia: el orden importa\',\\n  \'title_en\': \'4 \\u00b7 Phase and interference: order matters\',\\n  \'text\': \'Pens\\u00e1 en ondas que pueden reforzarse o cancelarse. Las amplitudes cu\\u00e1nticas se combinan \'\\n          \'de esa manera. La fase indica c\\u00f3mo se alinean: dos estados pueden mostrar iguales \'\\n          \'porcentajes ahora y dar resultados distintos despu\\u00e9s de otra compuerta.\',\\n  \'text_en\': \'Think of waves reinforcing or cancelling each other. Quantum amplitudes combine that \'\\n             \'way. Phase describes how they align: two states can show the same percentages now \'\\n             \'and behave differently after another gate.\',\\n  \'example\': \'H \\u2192 H vuelve a original. H \\u2192 Z \\u2192 H termina en ligada. Z no cambi\\u00f3 los porcentajes \'\\n             \'inmediatamente, pero cambi\\u00f3 c\\u00f3mo la \\u00faltima H combin\\u00f3 las amplitudes. No medimos \'\\n             \'entre esas operaciones.\',\\n  \'example_en\': \'H \\u2192 H returns to original. H \\u2192 Z \\u2192 H ends in linked. Z did not immediately change \'\\n                \'the percentages, but changed how the last H combined amplitudes. We do not \'\\n                \'measure between these operations.\',\\n  \'technical\': \'H(\\u03b1|0\\u27e9 + \\u03b2|1\\u27e9) = ((\\u03b1+\\u03b2)|0\\u27e9 + (\\u03b1\\u2212\\u03b2)|1\\u27e9)/\\u221a2. Z cambia \\u03b2 por \\u2212\\u03b2. El signo afecta la \'\\n               \'interferencia, no produce probabilidades negativas. Una fase global com\\u00fan a ambas \'\\n               \'amplitudes no cambia resultados observables.\',\\n  \'technical_en\': \'H(\\u03b1|0\\u27e9 + \\u03b2|1\\u27e9) = ((\\u03b1+\\u03b2)|0\\u27e9 + (\\u03b1\\u2212\\u03b2)|1\\u27e9)/\\u221a2. Z changes \\u03b2 to \\u2212\\u03b2. The sign affects \'\\n                  \'interference, not the non-negativity of probabilities. A global phase shared by \'\\n                  \'both amplitudes changes no observable outcome.\',\\n  \'circuits\': [[\'H\', \'X\'], [\'X\', \'H\'], [\'H\', \'Z\', \'H\']],\\n  \'sample\': True},\\n {\'title\': \'Mano guiada con Bot Q\',\\n  \'title_en\': \'A guided hand with Bot Q\',\\n  \'text\': \'Eleg\\u00ed una carta y hasta tres fichas. Bot Q cantar\\u00e1 Truco: prob\\u00e1 \\u201cEnvido va primero\\u201d. \'\\n          \'Respond\\u00e9 al Truco despu\\u00e9s de resolver los tantos y jug\\u00e1 las bazas. Bot Q solo aparece \'\\n          \'en esta mano. Al terminar pod\\u00e9s pasar a la explicaci\\u00f3n final del ruido.\',\\n  \'text_en\': \'Choose a card and up to three tokens. Bot Q will call Truco: try \\u201cEnvido goes \'\\n             \'first\\u201d. After the totals are resolved, answer Truco and play the tricks. Bot Q \'\\n             \'appears only in this hand. At the end, continue to the final noise lesson.\',\\n  \'example\': \'Confirmar bloquea tu circuito, pero no mide. La carta Q se mide al jugarla o aceptar \'\\n             \'Envido. Con privacidad, solo la persona que tiene el turno debe mirar su mano.\',\\n  \'example_en\': \'Confirming locks your circuit, without measuring. The Q card is measured when \'\\n                \'played or Envido accepted. With privacy enabled, only the player whose turn it is \'\\n                \'should look at their hand.\',\\n  \'circuits\': [],\\n  \'sample\': False,\\n  \'guided\': True},\\n {\'title\': \'5 \\u00b7 Ruido: un qubit tambi\\u00e9n cambia al esperar\',\\n  \'title_en\': \'5 \\u00b7 Noise: waiting can change a qubit\',\\n  \'text\': \'Un qubit real interact\\u00faa con su entorno. Puede perder energ\\u00eda y la coherencia que \'\\n          \'permite interferir. En el juego simulamos ambas cosas: despu\\u00e9s de confirmar, el reloj \'\\n          \'corre mientras pens\\u00e1s un turno visible. No corre durante avisos, privacidad, men\\u00fa ni \'\\n          \'pesta\\u00f1as ocultas. Una carta ya medida queda fija.\',\\n  \'text_en\': \'A real qubit interacts with its environment. It can lose energy and the coherence \'\\n             \'that enables interference. This game simulates both: after confirmation, the clock \'\\n             \'runs during your visible decision time. Notices, privacy, menus and hidden tabs \'\\n             \'pause it. A measured card stays fixed.\',\\n  \'example\': \'Con H empez\\u00e1s en 50/50. Esperar acerca la distribuci\\u00f3n a original en este modelo. El \'\\n             \'ruido no siempre acerca todo a 50/50: depende del canal y del estado. Los segundos \'\\n             \'se ampliaron para ense\\u00f1ar; no son tiempos de un dispositivo IonQ.\',\\n  \'example_en\': \'H starts at 50/50. Waiting moves the distribution toward original in this model. \'\\n                \'Noise does not always move everything toward 50/50: it depends on the channel and \'\\n                \'state. Times are scaled for teaching, not calibrated to an IonQ device.\',\\n  \'technical\': \'El programa evoluciona una matriz de densidad \\u03c1 con operadores de Kraus de \'\\n               \'relajaci\\u00f3n y desfasaje. Los porcentajes mostrados son las diagonales de esa misma \'\\n               \'matriz que se usa para muestrear con Qiskit. Es ruido f\\u00edsico modelado, no un \'\\n               \'porcentaje aleatorio decorativo.\',\\n  \'technical_en\': \'The program evolves a density matrix \\u03c1 using amplitude-damping and dephasing \'\\n                  \'Kraus operators. Displayed percentages are the diagonal entries of the same \'\\n                  \'matrix sampled by Qiskit. This is a physical noise model, not decorative random \'\\n                  \'percentages.\',\\n  \'circuits\': [[\'H\']],\\n  \'sample\': True,\\n  \'noise\': True}]\\n","service":"\\"\\"\\"Session API shared by local HTTP and Qollab Python imports.\\"\\"\\"\\nimport json\\nimport platform\\nimport qiskit\\nfrom .game import Game\\nfrom .quantum import LocalSampler, preview, noise_view\\nfrom .remote import RemoteMeasurement\\nfrom .tutorial import LESSONS\\n\\nclass Session:\\n    def __init__(self, local=False):\\n        self.local = local\\n        self.host_local = local\\n        self.game = None\\n        self.remote = None\\n        self.tutorial_index = 0\\n        self.tutorial_result = None\\n        self.tutorial_pending = None\\n        self.tutorial_noise_seconds = 30\\n        self.guided = False\\n        self.error = None\\n        self.errors = []\\n    def output(self, private=False):\\n        result = {\'mode\':LocalSampler.name if self.local else \'Qollab \\u00b7 IonQ injected backend \\u00b7 one-job limit\',\\n                  \'development_mode\':self.local, \'host_local\':self.host_local,\\n                  \'versions\':{\'python\':platform.python_version(),\'qiskit\':qiskit.__version__},\\n                  \'error\':self.error,\'guided\':self.guided, \'remote_info\':self.remote.info() if self.remote else None,\\n                  \'remote_error\':self.remote.last_error if self.remote else None}\\n        if self.game:\\n            result[\'game\'] = self.game.public_view()\\n            if private: result[\'private\'] = self.game.private_view()\\n        lesson = LESSONS[self.tutorial_index]\\n        result[\'tutorial\'] = {**lesson,\'index\':self.tutorial_index,\'total\':len(LESSONS),\\n                              \'previews\':[noise_view(c,self.tutorial_noise_seconds) if lesson.get(\'noise\') else preview(c) for c in lesson[\'circuits\']],\\n                              \'noise_seconds\':self.tutorial_noise_seconds,\\n                              \'result\':self.tutorial_result, \'pending\':self.tutorial_pending is not None}\\n        return result\\n    def bot(self):\\n        if not self.guided or not self.game: return\\n        g = self.game\\n        for _ in range(10):\\n            if g.actor != 1: break\\n            if g.phase == \'prepare\':\\n                g.dispatch(\'choose\',0); g.dispatch(\'confirm\')\\n                g.dispatch(\'truco\'); break\\n            if g.phase == \'respond\': g.dispatch(\'accept\')\\n            elif g.phase == \'reassert\': g.dispatch(\'reassert\')\\n            elif g.phase == \'play\': g.dispatch(\'play\', next(i for i in range(3) if i not in g.played[1]))\\n            else: break\\n    def action(self, payload):\\n        self.error = None\\n        action = payload[\'action\']; value = payload.get(\'value\')\\n        if self.tutorial_pending is not None and action not in (\'public\',\'reveal\',\'dev_mode\'):\\n            raise ValueError(\'El tutorial tiene una medici\\u00f3n pendiente. Consult\\u00e1 su resultado antes de continuar.\')\\n        if action in (\'new\',\'guided\',\'tutorial\') and self.needs_measurement():\\n            raise ValueError(\'Hay una medici\\u00f3n pendiente. Completala o consult\\u00e1 su resultado antes de cambiar de partida o lecci\\u00f3n.\')\\n        if action == \'dev_mode\':\\n            if type(value) is not bool: raise ValueError(\'Modo inv\\u00e1lido\')\\n            if self.host_local and not value: raise ValueError(\'El servidor local solo admite modo de desarrollo\')\\n            if value != self.local and self.remote and self.remote.started is not None:\\n                raise ValueError(\'Consult\\u00e1 el resultado IonQ pendiente antes de cambiar el modo de medici\\u00f3n.\')\\n            self.local = value\\n        elif action == \'new\':\\n            if isinstance(value,dict) and value.get(\'noise\',False) and not self.local:\\n                raise ValueError(\'El ruido educativo requiere simulaci\\u00f3n local con Qiskit; no se agrega a IonQ.\')\\n            game = Game(value.get(\'names\'), privacy=value.get(\'privacy\', False), noise=value.get(\'noise\',False)) if isinstance(value, dict) else Game(value)\\n            self.guided = False\\n            self.game = game\\n        elif action == \'guided\':\\n            game = Game([value or \'Vos\',\'Bot Q\'], noise=self.local)\\n            self.guided = True\\n            self.game = game\\n            self.game.mano = 1; self.game.actor = self.game.turn = 0\\n            self.game.events[0][\'mano\'] = 1\\n        elif action == \'tutorial\':\\n            if type(value) is not int or not 0 <= value < len(LESSONS): raise ValueError(\'Lecci\\u00f3n inv\\u00e1lida\')\\n            self.tutorial_index = value; self.tutorial_result = None\\n            self.tutorial_noise_seconds = 30\\n        elif action == \'tutorial_noise\':\\n            if not LESSONS[self.tutorial_index].get(\'noise\') or type(value) is not int or value not in (0,15,30,60):\\n                raise ValueError(\'Experimento de ruido inv\\u00e1lido\')\\n            self.tutorial_noise_seconds = value; self.tutorial_result = None\\n        elif action == \'noise_tick\':\\n            if not self.local or not self.game or not self.game.noise:\\n                raise ValueError(\'El ruido educativo no est\\u00e1 activo\')\\n            g=self.game\\n            if not isinstance(value,dict) or type(value.get(\'hand\')) is not int or type(value.get(\'player\')) is not int or value.get(\'hand\') != g.hand_number or value.get(\'player\') != g.actor or g.phase not in (\'play\',\'respond\',\'reassert\'):\\n                raise ValueError(\'El turno del ruido cambi\\u00f3\')\\n            g.q[g.actor].age(value.get(\'seconds\'))\\n            return self.output(private=True)\\n        elif action == \'tutorial_sample\':\\n            if self.game is not None and self.game.phase == \'measure\':\\n                raise ValueError(\'Primero complet\\u00e1 la medici\\u00f3n pendiente de la partida.\')\\n            if self.tutorial_pending is not None: raise ValueError(\'Ya hay una medici\\u00f3n pendiente\')\\n            circuits = LESSONS[self.tutorial_index][\'circuits\']\\n            if not LESSONS[self.tutorial_index][\'sample\']: raise ValueError(\'Esta lecci\\u00f3n no mide\')\\n            if type(value) is not int or not 0 <= value < len(circuits): raise ValueError(\'Circuito inv\\u00e1lido\')\\n            self.tutorial_pending = circuits[value]\\n        elif action == \'reveal\': return self.output(private=True)\\n        elif action == \'public\': return self.output()\\n        else:\\n            if self.game is None: raise ValueError(\'Inici\\u00e1 una partida\')\\n            self.game.dispatch(action,value)\\n            self.bot()\\n        return self.output(private=action in (\'choose\',\'edit\'))\\n    def needs_measurement(self):\\n        return self.tutorial_pending is not None or (self.game is not None and self.game.phase==\'measure\')\\n    def sequences(self):\\n        if self.tutorial_pending is not None: return [self.tutorial_pending]\\n        return [self.game.q[p].gates for p in self.game.measure_requests]\\n    def accept_measurements(self, measurements):\\n        if self.tutorial_pending is not None:\\n            bit, record = measurements[0]\\n            self.tutorial_result = {\'bit\':bit,\'record\':record,\\n                \'text\':f\'El resultado fue {bit}: \'+(\'original |0\\u27e9.\' if bit==0 else \'ligada |1\\u27e9.\')+\' Ahora permanece fijo. Repetir es un experimento nuevo.\'}\\n            self.tutorial_pending = None\\n        else:\\n            self.game.complete_measure(measurements)\\n            self.bot()\\n    def start(self, backend=None):\\n        if not self.needs_measurement(): return self.output()\\n        if self.local:\\n            sampler = LocalSampler()\\n            times = [self.tutorial_noise_seconds if LESSONS[self.tutorial_index].get(\'noise\') else None] if self.tutorial_pending is not None else [self.game.q[p].noise_seconds if self.game.noise else None for p in self.game.measure_requests]\\n            self.accept_measurements([sampler.sample(gates, seconds) for gates,seconds in zip(self.sequences(),times)])\\n            return self.output()\\n        if self.tutorial_pending is not None and LESSONS[self.tutorial_index].get(\'noise\'):\\n            raise ValueError(\'Eleg\\u00ed simulaci\\u00f3n local para medir este modelo de ruido educativo; no se env\\u00eda a IonQ.\')\\n        if self.tutorial_pending is None and self.game.noise:\\n            raise ValueError(\'Esta partida usa ruido educativo local. Eleg\\u00ed simulaci\\u00f3n local para medirla; no se env\\u00eda a IonQ.\')\\n        if self.remote is None: self.remote = RemoteMeasurement(backend)\\n        self.remote.start(self.sequences())\\n        return self.output()\\n    def poll(self):\\n        if self.local: return {\'done\':True,\'view\':self.output()}\\n        response = self.remote.poll()\\n        if response[\'done\']:\\n            self.accept_measurements(response[\'measurements\'])\\n            self.remote.release()\\n        return {\'done\':response[\'done\'],\'view\':self.output()}\\n    def safe(self, fn):\\n        self.error = None\\n        try: return fn()\\n        except (ValueError,RuntimeError,TimeoutError) as exc:\\n            self.error = str(exc)\\n            self.errors.append({\'type\':type(exc).__name__,\'message\':self.error})\\n            return self.output()\\n        except Exception as exc:\\n            # Do not return arbitrary provider errors which can contain credentials.\\n            self.error = f\'Fall\\u00f3 la operaci\\u00f3n ({type(exc).__name__}). No se gener\\u00f3 un resultado.\'\\n            self.errors.append({\'type\':type(exc).__name__})\\n            return self.output()\\n\\n# In Qollab the Python module is imported once per run; all state stays in memory.\\n_session = Session()\\n\\ndef dispatch_json(payload):\\n    return json.dumps(_session.safe(lambda:_session.action(json.loads(payload))))\\n\\ndef start_json(backend):\\n    return json.dumps(_session.safe(lambda:_session.start(backend)))\\n\\ndef poll_json():\\n    return json.dumps(_session.safe(_session.poll))\\n\\n\\ndef demo_json():\\n    import base64\\n    # Source checkouts keep artifacts/; Qollab\'s flat upload keeps root files.\\n    for prefix in (\'artifacts/\', \'\'):\\n        try:\\n            with open(prefix + \'truco-cuantico-demo.mp4\', \'rb\') as f:\\n                data = base64.b64encode(f.read()).decode(\'ascii\')\\n            with open(prefix + \'DEMO_TRANSCRIPT.txt\', encoding=\'utf8\') as f:\\n                transcript = f.read()\\n            return json.dumps({\'data\':data,\'transcript\':transcript})\\n        except OSError:\\n            continue\\n    return json.dumps({\'error\':\'Video no disponible en este paquete. Consult\\u00e1 DEMO_SCRIPT.md.\'})\\n"}')
_SERVICE = None


def _service():
    global _SERVICE
    if _SERVICE is None:
        root = '_qriollo_qollab'
        package = types.ModuleType(root)
        package.__path__ = []
        package.__package__ = root
        sys.modules[root] = package
        exec(compile(_SOURCES['__init__'], '<qollab_engine/__init__.py>', 'exec'), package.__dict__)
        for name in ('gates', 'classic', 'quantum', 'remote', 'game', 'tutorial', 'service'):
            module = types.ModuleType(root + '.' + name)
            module.__package__ = root
            module.__file__ = '<qollab_engine/' + name + '.py>'
            sys.modules[module.__name__] = module
            setattr(package, name, module)
            exec(compile(_SOURCES[name], module.__file__, 'exec'), module.__dict__)
        _SERVICE = sys.modules[root + '.service']
    return _SERVICE


def dispatch_json(payload):
    return _service().dispatch_json(payload)


def start_json(backend):
    return _service().start_json(backend)


def poll_json():
    return _service().poll_json()


def demo_json():
    return _service().demo_json()
